import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import {
  User,
  Mail,
  Crown,
  Calendar,
  Activity,
  Sparkles,
} from "lucide-react";

import api from "../services/api";

function Profile() {
  const navigate = useNavigate();

  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      const response = await api.get("/api/auth/me");

      setProfile(response.data.user);
    } catch (err) {
      toast.error(
        err.response?.data?.detail ||
          "Unable to load profile."
      );
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (value) => {
    if (!value) return "-";

    const date = new Date(value);

    if (isNaN(date.getTime())) return "-";

    return date.toLocaleDateString(undefined, {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  return (
    <div className="min-h-screen bg-slate-50 py-10 px-6">

      <div className="mx-auto max-w-6xl">

        {/* Header */}

        <div className="mb-8">
          <h1 className="text-4xl font-bold text-[#1E3A5F]">
            My Profile
          </h1>

          <p className="mt-2 text-gray-500">
            Manage your Gigora account and subscription.
          </p>
        </div>

        <div className="rounded-3xl bg-white p-10 shadow-lg">

          {loading ? (

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">

              {[...Array(6)].map((_, index) => (
                <div
                  key={index}
                  className="h-32 animate-pulse rounded-3xl bg-slate-200"
                />
              ))}

            </div>

          ) : profile ? (

            <>

              {/* Profile Header */}

              <div className="mb-12 flex flex-col items-center">

                <div className="flex h-28 w-28 items-center justify-center rounded-full bg-[#EFF6FF]">

                  <User
                    size={60}
                    className="text-[#1A56DB]"
                  />

                </div>

                <h2 className="mt-5 text-3xl font-bold text-[#1E3A5F]">
                  {profile.name}
                </h2>

                <p className="mt-2 text-gray-500">
                  {profile.email}
                </p>

                <div className="mt-5">

                  {profile.plan === "pro" ? (

                    <span className="inline-flex items-center gap-2 rounded-full bg-yellow-100 px-5 py-2 font-semibold text-yellow-700">

                      <Crown size={18} />

                      PRO MEMBER

                    </span>

                  ) : (

                    <span className="inline-flex items-center gap-2 rounded-full bg-[#EFF6FF] px-5 py-2 font-semibold text-[#1A56DB]">

                      <Sparkles size={18} />

                      FREE PLAN

                    </span>

                  )}

                </div>

              </div>

              {/* Info Cards */}

              <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">

                <Card
                  icon={<User className="text-[#1A56DB]" />}
                  title="Full Name"
                  value={profile.name}
                />

                <Card
                  icon={<Mail className="text-[#1A56DB]" />}
                  title="Email"
                  value={profile.email}
                />

                <Card
                  icon={<Crown className="text-[#1A56DB]" />}
                  title="Current Plan"
                  value={profile.plan?.toUpperCase()}
                />

                <Card
                  icon={<Calendar className="text-[#1A56DB]" />}
                  title="Joined"
                  value={formatDate(profile.created_at)}
                />

                <Card
                  icon={<Activity className="text-[#1A56DB]" />}
                  title="Requests Used"
                  value={profile.requests_used ?? 0}
                />

                <Card
                  icon={<Activity className="text-green-600" />}
                  title="Remaining Requests"
                  value={
                    profile.plan === "pro"
                      ? "Unlimited"
                      : profile.remaining_requests ?? 0
                  }
                />

              </div>

              {/* Button */}

              <div className="mt-12 flex justify-center">

                {profile.plan === "pro" ? (

                  <button
                    disabled
                    className="rounded-xl bg-green-600 px-10 py-4 font-semibold text-white"
                  >
                    ✓ Current Plan
                  </button>

                ) : (

                  <button
                    onClick={() => navigate("/pricing")}
                    className="rounded-xl bg-[#1A56DB] px-10 py-4 font-semibold text-white transition hover:bg-[#1E3A5F]"
                  >
                    Upgrade to Pro
                  </button>

                )}

              </div>

            </>

          ) : (

            <div className="rounded-2xl border border-red-100 bg-red-50 p-10 text-center">

              <h2 className="text-2xl font-bold text-red-600">
                Unable to load profile
              </h2>

              <p className="mt-3 text-gray-600">
                Please login again and try once more.
              </p>

            </div>

          )}

        </div>

      </div>

    </div>
  );
}

function Card({ icon, title, value }) {
  return (
    <div className="rounded-2xl border border-slate-200 p-6 transition hover:-translate-y-1 hover:shadow-lg">

      <div className="mb-4">
        {icon}
      </div>

      <p className="text-sm text-gray-500">
        {title}
      </p>

      <h3 className="mt-2 break-all text-xl font-bold text-[#1E3A5F]">
        {value}
      </h3>

    </div>
  );
}

export default Profile;
